/*
 * A183122  Magnetic Tower of Hanoi, number of moves of disk number k,
 *          generated by a certain algorithm, yielding a "forward moving"
 *          non-optimal solution of the [NEUTRAL ; NEUTRAL ; NEUTRAL]
 *          pre-colored puzzle.
 * https://oeis.org/A183122
 *
 * Offset:    0    (a(0) is the first term)
 * Keywords:  nonn, easy, changed
 * Formula:   not stated
 * Range:     u8 n <= 6, u16 n <= 11, u32 n <= 21, u64 n <= 41, u128 n <= 82,
 *            big any n
 * Helpers:   none
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

/* OEIS A183122: Magnetic Tower of Hanoi (Non‑optimal solution moves per disk)
 * Recurrence (for n>6):
 *   a(n) = 3*a(n-1) + a(n-2) - 3*a(n-3)
 * Initial values:
 *   a(0)=0, a(1)=1, a(2)=3, a(3)=7, a(4)=19, a(5)=53, a(6)=153
 */
#include <stdlib.h>

static seq_t *cache = NULL;           /* cached values a(0)…a(k) */
static idx_t cache_size = 0;          /* number of elements stored (index+1) */
static size_t cache_cap = 0;          /* allocated capacity */

/* compute a(n) and cache intermediate values for subsequent calls */
seq_t a(idx_t n)
{
    /* initial values for n = 0 … 6 */
    static const seq_t init_vals[7] = {0, 1, 3, 7, 19, 53, 153};

    /* ensure the cache can store up to n */
    if ((idx_t)cache_cap <= n)
    {
        size_t new_cap = (size_t)n + 1;
        if (new_cap < 64) new_cap = 64;          /* start with reasonable size */
        while (new_cap <= cache_cap) new_cap <<= 1;   /* grow exponentially */
        seq_t *tmp = (seq_t *)realloc(cache, new_cap * sizeof(seq_t));
        if (!tmp) abort();                       /* out of memory */
        cache = tmp;
        cache_cap = new_cap;
    }

    /* initialise cache if not already done */
    if (cache_size == 0)
    {
        for (idx_t i = 0; i <= 6 && i < (idx_t)cache_cap; ++i)
            cache[i] = init_vals[i];
        cache_size = 7;
    }

    /* compute further terms up to n */
    for (idx_t i = cache_size; i <= n; ++i)
    {
        if (i <= 6)
            cache[i] = init_vals[i];
        else
        {
            /* a(i) = 3*a(i-1) + a(i-2) - 3*a(i-3) */
            seq_t t = cache[i - 1] * 3;
            t += cache[i - 2];
            t -= cache[i - 3] * 3;
            cache[i] = t;
        }
    }

    cache_size = n + 1;
    return cache[n];
}
